const HTML = "<!DOCTYPE html>\n<html lang=\"pt-br\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Onboarding Oficial - Grupo C. Diniz</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700;800&family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400&display=swap\" rel=\"stylesheet\">\n    \n    <!-- Iconografia Font Awesome -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css\">\n\n    <style>\n        :root {\n            --primary-green: #0F3D2E;\n            --primary-dark: #082119;\n            --accent-gold: #D4AF37;\n            --accent-gold-dark: #B3922E;\n            --off-white: #FBFBF9;\n            --pure-white: #FFFFFF;\n            --text-dark: #2D3436;\n            --text-muted: #5A605E;\n            --bg-dark: #121212;\n            --glass: rgba(255, 255, 255, 0.98);\n            --shadow-premium: 0 30px 60px -15px rgba(15, 61, 46, 0.12);\n            --shadow-premium-hover: 0 40px 80px -10px rgba(15, 61, 46, 0.2);\n            --transition-smooth: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);\n        }\n\n        * {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n            scroll-behavior: smooth;\n        }\n\n        body {\n            font-family: 'Montserrat', sans-serif;\n            background-color: var(--bg-dark);\n            color: var(--text-dark);\n            overflow: hidden;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        .side-nav {\n            position: fixed;\n            left: 35px;\n            top: 50%;\n            transform: translateY(-50%);\n            z-index: 1000;\n            display: flex;\n            flex-direction: column;\n            gap: 15px;\n            background: rgba(15, 61, 46, 0.2);\n            padding: 20px 12px;\n            border-radius: 40px;\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(212, 175, 55, 0.15);\n        }\n\n        .nav-dot {\n            width: 12px;\n            height: 12px;\n            border-radius: 50%;\n            border: 2px solid var(--accent-gold);\n            cursor: pointer;\n            transition: var(--transition-smooth);\n            position: relative;\n        }\n\n        .nav-dot.active {\n            background: var(--accent-gold);\n            transform: scale(1.5);\n            box-shadow: 0 0 10px var(--accent-gold);\n        }\n\n        .nav-dot::after {\n            content: attr(title);\n            position: absolute;\n            left: 28px;\n            top: 50%;\n            transform: translateY(-50%) translateX(10px);\n            background: var(--primary-green);\n            color: var(--pure-white);\n            padding: 6px 14px;\n            border-radius: 6px;\n            font-size: 11px;\n            font-weight: 500;\n            white-space: nowrap;\n            opacity: 0;\n            visibility: hidden;\n            transition: var(--transition-smooth);\n            border: 1px solid rgba(212, 175, 55, 0.3);\n            pointer-events: none;\n        }\n\n        .nav-dot:hover::after {\n            opacity: 1;\n            visibility: visible;\n            transform: translateY(-50%) translateX(0);\n        }\n\n        .mobile-header {\n            display: none;\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            background: var(--primary-green);\n            color: var(--pure-white);\n            padding: 15px 20px;\n            z-index: 1001;\n            box-shadow: 0 4px 20px rgba(0,0,0,0.15);\n            align-items: center;\n            justify-content: space-between;\n            border-bottom: 2px solid var(--accent-gold);\n        }\n\n        .mobile-logo {\n            font-family: 'Playfair Display', serif;\n            font-weight: 700;\n            font-size: 1.2rem;\n            letter-spacing: 1px;\n        }\n\n        .mobile-logo span {\n            color: var(--accent-gold);\n        }\n\n        .mobile-menu-btn {\n            background: none;\n            border: none;\n            color: var(--pure-white);\n            font-size: 1.4rem;\n            cursor: pointer;\n        }\n\n        .slide-wrapper {\n            width: 100vw;\n            height: 100vh;\n            overflow-y: scroll;\n            scroll-snap-type: y mandatory;\n        }\n\n        section {\n            width: 100vw;\n            height: 100vh;\n            scroll-snap-align: start;\n            position: relative;\n            background-color: var(--off-white);\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 40px 40px 40px 100px;\n            overflow-y: auto;\n        }\n\n        .glass-card {\n            background: var(--glass);\n            border-radius: 28px;\n            padding: 45px;\n            width: 100%;\n            max-width: 1150px;\n            border: 1px solid rgba(212, 175, 55, 0.15);\n            box-shadow: var(--shadow-premium);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .glass-card::before {\n            content: '';\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 6px;\n            height: 100%;\n            background: linear-gradient(to bottom, var(--accent-gold), var(--primary-green));\n        }\n\n        h3 {\n            font-family: 'Playfair Display', serif;\n            color: var(--primary-green);\n            line-height: 1.2;\n        }\n\n        h1 {\n            font-size: clamp(2.4rem, 5.5vw, 4.2rem);\n            font-weight: 700;\n        }\n\n        h2 {\n            font-size: clamp(1.6rem, 3.5vw, 2.4rem);\n            margin-bottom: 12px;\n            position: relative;\n            display: inline-block;\n            font-family: 'Playfair Display', serif;\n            color: var(--primary-green);\n            line-height: 1.2;\n        }\n\n        h2::after {\n            content: '';\n            display: block;\n            width: 60px;\n            height: 3px;\n            background: var(--accent-gold);\n            margin-top: 10px;\n            border-radius: 2px;\n        }\n\n        p {\n            font-size: clamp(0.9rem, 1.6vw, 1.05rem);\n            line-height: 1.7;\n            color: var(--text-dark);\n            margin-bottom: 18px;\n        }\n\n        .title-pre {\n            font-family: 'Montserrat', sans-serif;\n            font-weight: 500;\n            letter-spacing: 4px;\n            text-transform: uppercase;\n            font-size: 0.8rem;\n            color: var(--accent-gold);\n            margin-bottom: 8px;\n        }\n\n        .btn-action {\n            background: linear-gradient(135deg, var(--primary-green) 0%, #155541 100%);\n            color: var(--pure-white);\n            padding: 16px 36px;\n            border-radius: 50px;\n            border: none;\n            cursor: pointer;\n            font-family: 'Montserrat';\n            font-weight: 700;\n            font-size: 0.85rem;\n            letter-spacing: 1px;\n            display: inline-flex;\n            align-items: center;\n            gap: 12px;\n            transition: var(--transition-smooth);\n            text-decoration: none;\n            box-shadow: 0 10px 20px -5px rgba(15, 61, 46, 0.3);\n        }\n\n        .btn-action:hover {\n            background: var(--accent-gold);\n            color: var(--primary-green);\n            transform: translateY(-3px);\n            box-shadow: 0 15px 25px -5px rgba(212, 175, 55, 0.4);\n        }\n\n        .btn-gold-outline {\n            background: transparent;\n            border: 2px solid var(--accent-gold);\n            color: var(--primary-green);\n            padding: 12px 24px;\n            border-radius: 50px;\n            font-family: 'Montserrat';\n            font-weight: 600;\n            font-size: 0.8rem;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n            display: inline-flex;\n            align-items: center;\n            gap: 10px;\n        }\n\n        .btn-gold-outline:hover {\n            background: var(--accent-gold);\n            color: var(--pure-white);\n            transform: translateY(-2px);\n        }\n\n        #capa {\n            background: radial-gradient(circle at 80% 20%, rgba(22, 78, 61, 0.15) 0%, transparent 50%),\n                        linear-gradient(135deg, var(--primary-green) 0%, var(--primary-dark) 100%);\n        }\n\n        #capa .glass-card {\n            background: rgba(15, 61, 45, 0.45);\n            border-color: rgba(212, 175, 55, 0.3);\n            color: var(--pure-white);\n            text-align: center;\n        }\n\n        #capa h1, #capa p {\n            color: var(--pure-white);\n        }\n\n        #capa .glass-card::before {\n            background: var(--accent-gold);\n        }\n\n        .brand-icons-bar {\n            display: flex;\n            justify-content: center;\n            gap: 30px;\n            margin-top: 40px;\n            font-size: 1.5rem;\n            color: var(--accent-gold);\n        }\n\n        .carmen-grid {\n            display: grid;\n            grid-template-columns: 1.2fr 0.8fr;\n            gap: 40px;\n            align-items: center;\n        }\n\n        .carmen-avatar-container {\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            position: relative;\n        }\n\n        .carmen-bullets {\n            background: #F4F6F4;\n            padding: 20px;\n            border-radius: 16px;\n            margin-top: 20px;\n            border-left: 4px solid var(--accent-gold);\n            width: 100%;\n            transition: var(--transition-smooth);\n        }\n\n        .carmen-bullets:hover {\n            transform: translateY(-5px);\n            background: var(--pure-white);\n            box-shadow: 0 15px 30px rgba(15, 61, 46, 0.08);\n        }\n\n        .carmen-bullets ul {\n            list-style: none;\n        }\n\n        .carmen-bullets ul li {\n            font-size: 0.85rem;\n            font-weight: 600;\n            color: var(--primary-green);\n            margin-bottom: 8px;\n            display: flex;\n            align-items: center;\n            gap: 10px;\n        }\n\n        .timeline-container {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 20px;\n            margin-top: 25px;\n        }\n\n        .timeline-column {\n            display: flex;\n            flex-direction: column;\n            gap: 12px;\n        }\n\n        .timeline-card {\n            background: #F4F6F4;\n            border-radius: 14px;\n            padding: 16px 20px;\n            display: flex;\n            gap: 15px;\n            align-items: flex-start;\n            border: 1px solid transparent;\n            transition: var(--transition-smooth);\n        }\n\n        .timeline-card:hover {\n            transform: translateY(-3px);\n            background: var(--pure-white);\n            border-color: var(--accent-gold);\n            box-shadow: 0 10px 20px rgba(15, 61, 46, 0.05);\n        }\n\n        .timeline-year {\n            background: var(--primary-green);\n            color: var(--pure-white);\n            font-weight: 700;\n            font-size: 0.85rem;\n            padding: 6px 12px;\n            border-radius: 8px;\n            min-width: 60px;\n            text-align: center;\n            border: 1px solid var(--accent-gold);\n            transition: var(--transition-smooth);\n        }\n\n        .timeline-card:hover .timeline-year {\n            background: var(--accent-gold);\n            color: var(--primary-green);\n        }\n\n        .timeline-year.current-highlight {\n            background: var(--accent-gold);\n            color: var(--primary-green);\n        }\n\n        .timeline-content h4 {\n            font-size: 0.85rem;\n            color: var(--primary-green);\n            font-weight: 700;\n            margin-bottom: 4px;\n        }\n\n        .timeline-content p {\n            font-size: 0.78rem;\n            color: var(--text-muted);\n            margin-bottom: 0;\n            line-height: 1.4;\n        }\n\n        .map-wrapper-outer {\n            width: 100%;\n            height: 440px;\n            border-radius: 20px;\n            overflow: hidden;\n            box-shadow: var(--shadow-premium);\n            border: 2px solid rgba(212, 175, 55, 0.3);\n            background: transparent;\n            position: relative;\n            transition: var(--transition-smooth);\n        }\n\n        .map-wrapper-outer:hover {\n            border-color: var(--accent-gold);\n            box-shadow: var(--shadow-premium-hover);\n        }\n\n        .map-wrapper-inner {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: calc(100% + 52px);\n            clip-path: inset(52px 0px 0px 0px);\n            transform: translateY(-52px);\n        }\n\n        .map-wrapper-inner iframe {\n            width: 100%;\n            height: 100%;\n            border: none;\n            background: transparent;\n        }\n\n        .distribution-grid {\n            display: grid;\n            grid-template-columns: 1.1fr 0.9fr;\n            gap: 30px;\n            margin-top: 25px;\n        }\n\n        .dist-card-box {\n            background: var(--pure-white);\n            border-radius: 20px;\n            padding: 30px;\n            border: 1px solid #EDEFE9;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.01);\n            transition: var(--transition-smooth);\n        }\n\n        .dist-card-box:hover {\n            border-color: var(--accent-gold);\n            box-shadow: var(--shadow-premium-hover);\n        }\n\n        .dist-card-box h3 {\n            font-size: 1.2rem;\n            display: flex;\n            align-items: center;\n            gap: 12px;\n            margin-bottom: 20px;\n            padding-bottom: 10px;\n            border-bottom: 2px solid #F4F6F4;\n        }\n\n        .dist-card-box.vd h3 {\n            border-bottom-color: rgba(212, 175, 55, 0.2);\n        }\n\n        .dist-card-box h3 i {\n            padding: 10px;\n            border-radius: 10px;\n            font-size: 1.1rem;\n        }\n\n        .dist-card-box.lojas h3 i { background: rgba(15, 61, 46, 0.08); color: var(--primary-green); }\n        .dist-card-box.vd h3 i { background: rgba(212, 175, 55, 0.12); color: var(--accent-gold-dark); }\n\n        .code-items-list {\n            display: flex;\n            flex-direction: column;\n            gap: 10px;\n        }\n\n        .code-row-item {\n            background: #F8F9F6;\n            border-radius: 10px;\n            padding: 12px 16px;\n            display: flex;\n            align-items: center;\n            gap: 15px;\n            transition: var(--transition-smooth);\n            border-left: 4px solid transparent;\n        }\n\n        .dist-card-box.lojas .code-row-item { border-left-color: var(--primary-green); }\n        .dist-card-box.vd .code-row-item { border-left-color: var(--accent-gold); }\n\n        .code-row-item:hover {\n            transform: translateX(5px);\n            background: var(--pure-white);\n            box-shadow: 0 5px 15px rgba(0,0,0,0.03);\n        }\n\n        .code-badge {\n            font-family: 'Montserrat', sans-serif;\n            font-weight: 700;\n            font-size: 0.75rem;\n            padding: 4px 10px;\n            border-radius: 4px;\n            min-width: 60px;\n            text-align: center;\n        }\n\n        .dist-card-box.lojas .code-badge { background: rgba(15, 61, 46, 0.06); color: var(--primary-green); }\n        .dist-card-box.vd .code-badge { background: rgba(212, 175, 55, 0.15); color: var(--accent-gold-dark); }\n\n        .code-name {\n            font-size: 0.85rem;\n            font-weight: 600;\n            color: var(--text-dark);\n            flex: 1;\n        }\n\n        .essencia-grid {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 20px;\n        }\n\n        .essencia-card {\n            background: var(--pure-white);\n            padding: 30px 25px;\n            border-radius: 20px;\n            border: 1px solid #EDEDED;\n            text-align: center;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.01);\n            transition: var(--transition-smooth);\n        }\n\n        .essencia-card:hover {\n            transform: translateY(-5px);\n            border-color: var(--accent-gold);\n            box-shadow: var(--shadow-premium-hover);\n        }\n\n        .essencia-icon {\n            width: 60px;\n            height: 60px;\n            background: rgba(212, 175, 55, 0.1);\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            margin: 0 auto 15px;\n            font-size: 1.5rem;\n            color: var(--accent-gold-dark);\n            transition: var(--transition-smooth);\n        }\n\n        .essencia-card:hover .essencia-icon {\n            background: var(--primary-green);\n            color: var(--accent-gold);\n            transform: rotateY(180deg);\n        }\n\n        .valores-list {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 10px;\n            margin-top: 15px;\n        }\n\n        .valor-item {\n            background: #F4F6F4;\n            padding: 8px;\n            border-radius: 8px;\n            font-size: 0.8rem;\n            font-weight: 600;\n            color: var(--primary-green);\n            text-align: center;\n            transition: var(--transition-smooth);\n        }\n\n        .rules-grid {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 30px;\n            margin-top: 20px;\n        }\n\n        .rules-card {\n            background: var(--pure-white);\n            padding: 30px;\n            border-radius: 20px;\n            border: 1px solid #ECECEC;\n            display: flex;\n            flex-direction: column;\n            justify-content: space-between;\n            transition: var(--transition-smooth);\n        }\n\n        .rules-card:hover {\n            transform: translateY(-5px);\n            border-color: var(--accent-gold);\n            box-shadow: var(--shadow-premium-hover);\n        }\n\n        .policies-controls {\n            display: flex;\n            gap: 15px;\n            margin-bottom: 20px;\n            flex-wrap: wrap;\n        }\n\n        .policy-search {\n            flex: 1;\n            min-width: 250px;\n            padding: 12px 20px;\n            border-radius: 50px;\n            border: 1px solid #DDD;\n            font-family: 'Montserrat';\n            font-size: 0.85rem;\n            outline: none;\n            transition: var(--transition-smooth);\n        }\n\n        .policy-search:focus {\n            border-color: var(--primary-green);\n            box-shadow: 0 0 0 3px rgba(15, 61, 46, 0.1);\n        }\n\n        .policy-filter-btn {\n            padding: 12px 25px;\n            border-radius: 50px;\n            border: 1px solid #DDD;\n            background: var(--pure-white);\n            font-family: 'Montserrat';\n            font-weight: 600;\n            font-size: 0.8rem;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n        }\n\n        .policy-filter-btn:hover {\n            border-color: var(--primary-green);\n            transform: translateY(-2px);\n        }\n\n        .policy-filter-btn.active {\n            background: var(--primary-green);\n            color: var(--pure-white);\n            border-color: var(--primary-green);\n        }\n\n        .policy-list-container {\n            display: grid;\n            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\n            gap: 12px;\n            max-height: 320px;\n            overflow-y: auto;\n            padding-right: 8px;\n        }\n\n        .policy-list-container::-webkit-scrollbar {\n            width: 6px;\n        }\n\n        .policy-list-container::-webkit-scrollbar-thumb {\n            background: var(--accent-gold);\n            border-radius: 3px;\n        }\n\n        .policy-item-pill {\n            background: var(--pure-white);\n            border: 1px solid #ECECEC;\n            border-radius: 12px;\n            padding: 12px 16px;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n\n        .policy-item-pill:hover {\n            border-color: var(--accent-gold);\n            transform: translateY(-3px);\n            background: #FAFBF9;\n            box-shadow: 0 10px 20px rgba(15, 61, 46, 0.05);\n        }\n\n        .policy-item-pill i {\n            color: var(--accent-gold-dark);\n            font-size: 1.1rem;\n            transition: var(--transition-smooth);\n        }\n\n        .policy-item-pill:hover i {\n            transform: scale(1.2);\n            color: var(--primary-green);\n        }\n\n        .policy-item-pill span {\n            font-weight: 600;\n            font-size: 0.78rem;\n            line-height: 1.3;\n        }\n\n        .benefits-grid {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 20px;\n        }\n\n        .benefit-card {\n            background: var(--pure-white);\n            border-radius: 20px;\n            padding: 30px;\n            border: 1px solid #EDEFE9;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.01);\n            transition: var(--transition-smooth);\n        }\n\n        .benefit-card:hover {\n            transform: translateY(-5px);\n            border-color: var(--accent-gold);\n            box-shadow: var(--shadow-premium-hover);\n        }\n\n        .benefit-card h3 {\n            font-size: 1.1rem;\n            border-bottom: 2px solid var(--accent-gold);\n            padding-bottom: 10px;\n            margin-bottom: 15px;\n            transition: var(--transition-smooth);\n        }\n\n        .benefit-card ul {\n            list-style: none;\n        }\n\n        .benefit-card ul li {\n            font-size: 0.82rem;\n            line-height: 1.6;\n            margin-bottom: 10px;\n            position: relative;\n            padding-left: 20px;\n        }\n\n        .benefit-card ul li::before {\n            content: '•';\n            position: absolute;\n            left: 0;\n            color: var(--accent-gold);\n            font-size: 1.2rem;\n            top: -2px;\n        }\n\n        .closing-quote-card {\n            background: rgba(15, 61, 46, 0.05);\n            border: 1px solid rgba(212, 175, 55, 0.3);\n            border-radius: 20px;\n            padding: 30px;\n            margin-top: 35px;\n            text-align: center;\n        }\n\n        .closing-text {\n            font-family: 'Playfair Display', serif;\n            font-style: italic;\n            font-size: 1.15rem;\n            color: var(--primary-green);\n            line-height: 1.6;\n            margin-bottom: 15px;\n        }\n\n        .closing-author {\n            font-family: 'Montserrat', sans-serif;\n            font-weight: 700;\n            font-size: 0.85rem;\n            text-transform: uppercase;\n            letter-spacing: 2px;\n            color: var(--accent-gold-dark);\n        }\n\n        .modal-overlay {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(8, 33, 25, 0.96);\n            backdrop-filter: blur(8px);\n            display: none;\n            z-index: 2000;\n            justify-content: center;\n            align-items: center;\n            padding: 20px;\n        }\n\n        .modal-overlay.active {\n            display: flex;\n        }\n\n        .modal-content {\n            background: var(--off-white);\n            border-radius: 24px;\n            width: 100%;\n            max-width: 950px;\n            border: 2px solid var(--accent-gold);\n            box-shadow: 0 30px 60px rgba(0,0,0,0.4);\n            position: relative;\n            animation: modalFade 0.4s cubic-bezier(0.16, 1, 0.3, 1);\n            overflow: hidden;\n        }\n\n        @keyframes modalFade {\n            from { opacity: 0; transform: translateY(30px); }\n            to { opacity: 1; transform: translateY(0); }\n        }\n\n        .modal-header {\n            background: var(--primary-green);\n            color: var(--pure-white);\n            padding: 25px 35px;\n            position: relative;\n        }\n\n        .modal-header h3 {\n            color: var(--pure-white);\n            font-size: 1.5rem;\n            margin-bottom: 3px;\n        }\n\n        .modal-close {\n            position: absolute;\n            right: 25px;\n            top: 25px;\n            background: none;\n            border: none;\n            color: rgba(255,255,255,0.7);\n            font-size: 1.6rem;\n            cursor: pointer;\n            transition: var(--transition-smooth);\n        }\n\n        .modal-close:hover {\n            color: var(--accent-gold);\n            transform: rotate(90deg);\n        }\n\n        .modal-body {\n            padding: 35px;\n            max-height: 75vh;\n            overflow-y: auto;\n            font-size: 0.95rem;\n            line-height: 1.7;\n        }\n\n        .document-full-text {\n            font-size: 0.88rem;\n            color: var(--text-dark);\n            line-height: 1.8;\n            text-align: justify;\n        }\n\n        .document-full-text h3 {\n            font-size: 1.3rem;\n            color: var(--primary-green);\n            margin: 20px 0 12px 0;\n            border-bottom: 2px solid var(--accent-gold);\n            padding-bottom: 6px;\n        }\n\n        .document-full-text h4 {\n            font-size: 1.05rem;\n            color: var(--primary-green);\n            margin: 18px 0 10px 0;\n            font-weight: 700;\n        }\n\n        .document-full-text ol, .document-full-text ul {\n            margin-left: 20px;\n            margin-bottom: 15px;\n        }\n\n        .document-full-text li {\n            margin-bottom: 8px;\n            font-size: 0.88rem;\n        }\n\n        @media (max-width: 1024px) {\n            section { padding: 80px 30px 30px 30px; }\n            .side-nav { display: none; }\n            .mobile-header { display: flex; }\n            .carmen-grid, .timeline-container, .distribution-grid { grid-template-columns: 1fr; gap: 30px; }\n            .benefits-grid { grid-template-columns: 1fr; }\n        }\n\n        @media (max-width: 768px) {\n            .glass-card { padding: 30px 20px; border-radius: 20px; }\n            .essencia-grid, .rules-grid { grid-template-columns: 1fr; }\n        }\n    </style>\n</head>\n<body>\n\n    <header class=\"mobile-header\">\n        <div class=\"mobile-logo\">Grupo <span>C. Diniz</span></div>\n        <button class=\"mobile-menu-btn\" onclick=\"window.openNavMenu()\"><i class=\"fa-solid fa-bars\"></i></button>\n    </header>\n\n    <nav class=\"side-nav\" id=\"sideNav\">\n        <div class=\"nav-dot active\" data-target=\"capa\" title=\"Boas-vindas\"></div>\n        <div class=\"nav-dot\" data-target=\"video\" title=\"Vídeo Institucional\"></div>\n        <div class=\"nav-dot\" data-target=\"carmen\" title=\"A Fundadora\"></div>\n        <div class=\"nav-dot\" data-target=\"historia\" title=\"Nossa História\"></div>\n        <div class=\"nav-dot\" data-target=\"atuacao\" title=\"Área de Atuação\"></div>\n        <div class=\"nav-dot\" data-target=\"distribuicao\" title=\"Lojas e VD\"></div>\n        <div class=\"nav-dot\" data-target=\"essencia\" title=\"Nossa Essência\"></div>\n        <div class=\"nav-dot\" data-target=\"regulamento\" title=\"Regulamento Interno\"></div>\n        <div class=\"nav-dot\" data-target=\"organograma\" title=\"Organograma\"></div>\n        <div class=\"nav-dot\" data-target=\"politicas\" title=\"Políticas Oficiais\"></div>\n        <div class=\"nav-dot\" data-target=\"beneficios\" title=\"Benefícios Oficiais\"></div>\n    </nav>\n\n    <main class=\"slide-wrapper\" id=\"main-scroll\">\n        \n        <section id=\"capa\">\n            <div class=\"glass-card\" style=\"max-width: 950px;\">\n                <p class=\"title-pre\">Apresentação Institucional</p>\n                <h1>Grupo <span class=\"text-gold\">C. Diniz</span></h1>\n                <div style=\"width: 80px; height: 3px; background: var(--accent-gold); margin: 25px auto;\"></div>\n                <p style=\"font-size: 1.25rem; opacity: 0.95; max-width: 750px; margin: 0 auto 35px;\">\n                    Bem-vindo à integração oficial de nossa rede varejista. Há mais de 30 anos transformando e inovando o varejo de cosméticos, perfumaria e higiene pessoal.\n                </p>\n                <button class=\"btn-action\" onclick=\"window.scrollToSlide('video')\">\n                    INICIAR APRESENTAÇÃO <i class=\"fa-solid fa-arrow-right\"></i>\n                </button>\n                <div class=\"brand-icons-bar\">\n                    <i class=\"fa-solid fa-droplet\" title=\"O Boticário\"></i>\n                    <i class=\"fa-solid fa-heart\" title=\"Quem Disse, Berenice?\"></i>\n                    <i class=\"fa-solid fa-sparkles\" title=\"O.U.i Paris\"></i>\n                    <i class=\"fa-solid fa-gem\" title=\"Eudora\"></i>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"video\">\n            <div class=\"glass-card\" style=\"text-align: center;\">\n                <p class=\"title-pre\">Apresentação Institucional</p>\n                <h2>Vídeo Institucional</h2>\n                <p style=\"margin-bottom: 20px;\">Assista ao vídeo oficial de apresentação do Grupo C. Diniz:</p>\n                \n                <div style=\"width: 100%; max-width: 920px; height: 480px; margin: 0 auto; border-radius: 20px; overflow: hidden; box-shadow: var(--shadow-premium); border: 2px solid rgba(212, 175, 55, 0.3);\">\n                    <iframe src=\"https://drive.google.com/file/d/1ekBeFKFIrzxsMYMTX-zK9vpd2vsMZctA/preview\" width=\"100%\" height=\"100%\" allow=\"autoplay\" allowfullscreen style=\"border:0;\"></iframe>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"carmen\">\n            <div class=\"glass-card\">\n                <div class=\"carmen-grid\">\n                    <div>\n                        <p class=\"title-pre\">Perfil Profissional – Franqueada/Operadora</p>\n                        <h2>Carmen Neves Diniz</h2>\n                        \n                        <div class=\"timeline-column\" style=\"margin-top: 25px;\">\n                            <div class=\"timeline-card\">\n                                <div class=\"timeline-year current-highlight\"><i class=\"fa-solid fa-user-graduate\"></i></div>\n                                <div class=\"timeline-content\">\n                                    <h4>GRADUAÇÃO</h4>\n                                    <p>Bacharel em Administração - UFPB</p>\n                                </div>\n                            </div>\n                            <div class=\"timeline-card\">\n                                <div class=\"timeline-year current-highlight\"><i class=\"fa-solid fa-chart-pie\"></i></div>\n                                <div class=\"timeline-content\">\n                                    <h4>MBA</h4>\n                                    <p>Finanças - FAFICA</p>\n                                </div>\n                            </div>\n                            <div class=\"timeline-card\">\n                                <div class=\"timeline-year current-highlight\"><i class=\"fa-solid fa-building-user\"></i></div>\n                                <div class=\"timeline-content\">\n                                    <h4>PÓS-GRADUAÇÃO</h4>\n                                    <p>Planejamento e Gestão - UPE</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"carmen-avatar-container\">\n                        <div class=\"carmen-bullets\">\n                            <p style=\"font-weight: 700; color: var(--primary-green); margin-bottom: 15px; font-size: 0.95rem;\">Reconhecimento de Mercado:</p>\n                            <ul>\n                                <li><i class=\"fa-solid fa-check text-gold\"></i> Longevidade nos negócios (30+ anos)</li>\n                                <li><i class=\"fa-solid fa-check text-gold\"></i> Desenvolvimento do comércio local</li>\n                                <li><i class=\"fa-solid fa-check text-gold\"></i> Envolvimento em iniciativas sociais e educacionais</li>\n                            </ul>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"historia\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Linha do Tempo</p>\n                <h2>Nossa História</h2>\n                <p>O propósito de encantar, inovar e transformar o varejo de beleza todos os dias refletido em nossa história:</p>\n                \n                <div class=\"timeline-container\">\n                    <div class=\"timeline-column\">\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">1991</div>\n                            <div class=\"timeline-content\">\n                                <h4>Início da Franquia</h4>\n                                <p>Abertura da primeira loja em Santa Cruz do Capibaribe e o começo da venda direta informal.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">1999</div>\n                            <div class=\"timeline-content\">\n                                <h4>Expansão para Toritama - PE</h4>\n                                <p>Inauguração de mais uma loja no município de Toritama.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2001</div>\n                            <div class=\"timeline-content\">\n                                <h4>Chegada em Taquaritinga - PE</h4>\n                                <p>Abertura da loja em Taquaritinga do Norte, ampliando nossa presença.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2003</div>\n                            <div class=\"timeline-content\">\n                                <h4>Expansão em Santa Cruz do Capibaribe</h4>\n                                <p>Inauguração da segunda loja em Sta. Cruz do Capibaribe.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2004</div>\n                            <div class=\"timeline-content\">\n                                <h4>Aquisição em Surubim - PE</h4>\n                                <p>Aquisição estratégica da franquia na cidade de Surubim.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2006</div>\n                            <div class=\"timeline-content\">\n                                <h4>Inauguração em Vertentes - PE</h4>\n                                <p>Abertura da loja de Vertentes, fortalecendo nossa rede.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2011</div>\n                            <div class=\"timeline-content\">\n                                <h4>Central de Serviços SC</h4>\n                                <p>Abertura da Central de Serviços em Santa Cruz do Capibaribe - PE.</p>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"timeline-column\">\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2012</div>\n                            <div class=\"timeline-content\">\n                                <h4>Quiosque no Moda Center</h4>\n                                <p>Inauguração do quiosque no Moda Center em Santa Cruz do Capibaribe - PE.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2020</div>\n                            <div class=\"timeline-content\">\n                                <h4>Central de Serviços Surubim - PE</h4>\n                                <p>Abertura da Central de Serviços em Surubim.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2021</div>\n                            <div class=\"timeline-content\">\n                                <h4>Mudança em Taquaritinga do Norte</h4>\n                                <p>Transferência do quiosque e fechamento da loja em Taquaritinga.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2022</div>\n                            <div class=\"timeline-content\">\n                                <h4>1ª Tô que Tô em Vertentes - PE</h4>\n                                <p>Abertura da nossa primeira unidade \"Tô que Tô\" em Vertentes.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2023</div>\n                            <div class=\"timeline-content\">\n                                <h4>Abertura da VD Toritama - PE</h4>\n                                <p>Inauguração da Venda Direta (VD) em Toritama.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\">\n                            <div class=\"timeline-year\">2024</div>\n                            <div class=\"timeline-content\">\n                                <h4>Novas Lojas</h4>\n                                <p>Abertura da segunda loja em Surubim e da loja sustentável em Sta. Cruz do Capibaribe.</p>\n                            </div>\n                        </div>\n                        <div class=\"timeline-card\" style=\"border-color: var(--accent-gold);\">\n                            <div class=\"timeline-year\" style=\"background: var(--accent-gold); color: var(--primary-green);\">2025</div>\n                            <div class=\"timeline-content\">\n                                <h4 style=\"color: var(--accent-gold-dark);\">Reforma TQT para Boticário</h4>\n                                <p>Reforma da loja \"Tô que Tô\" em Vertentes para uma nova loja da Boticário.</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"atuacao\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Mapeamento de Pontos de Venda</p>\n                <h2>Área de Atuação</h2>\n                <p>Navegue geograficamente pelas operações e frentes comerciais ativas do Grupo C. Diniz no estado de Pernambuco:</p>\n                \n                <div class=\"map-wrapper-outer\">\n                    <div class=\"map-wrapper-inner\">\n                        <iframe src=\"https://www.google.com/maps/d/u/0/embed?mid=1lbf2SSZWq8svgbcYghT6lzGhQU7c7uA&ehbc=2E312F\"></iframe>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"distribuicao\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Unidades de Negócio</p>\n                <h2>Lojas e Venda Direta (VD)</h2>\n                <p>Confira a relação de códigos identificadores oficiais de nossa malha operacional de distribuição varejista e venda direta:</p>\n\n                <div class=\"distribution-grid\">\n                    <div class=\"dist-card-box lojas\">\n                        <h3><i class=\"fa-solid fa-store\"></i> Lojas Oficiais</h3>\n                        <div class=\"code-items-list\">\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">19493</span>\n                                <span class=\"code-name\">Surubim</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">19738</span>\n                                <span class=\"code-name\">Quiosque</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">20039</span>\n                                <span class=\"code-name\">Santa Cruz 1</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">20787</span>\n                                <span class=\"code-name\">Santa Cruz 2</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">21517</span>\n                                <span class=\"code-name\">Vertentes</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">21690</span>\n                                <span class=\"code-name\">Toritama</span>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">22996</span>\n                                <span class=\"code-name\">Surubim 2</span>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"dist-card-box vd\">\n                        <h3><i class=\"fa-solid fa-truck-ramp-box\"></i> Venda Direta (VD)</h3>\n                        <div class=\"code-items-list\">\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">20190</span>\n                                <span class=\"code-name\">Surubim</span>\n                                <i class=\"fa-solid fa-box-open\"></i>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">21997</span>\n                                <span class=\"code-name\">Toritama</span>\n                                <i class=\"fa-solid fa-box-open\"></i>\n                            </div>\n                            <div class=\"code-row-item\">\n                                <span class=\"code-badge\">13373</span>\n                                <span class=\"code-name\">Santa Cruz do Capibaribe</span>\n                                <i class=\"fa-solid fa-box-open\"></i>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"essencia\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Nossa Identidade</p>\n                <h2 style=\"display: block; text-align: center;\">Nossa Essência</h2>\n                <div class=\"essencia-intro\" style=\"font-style: italic; color: var(--primary-green); text-align: center; margin-bottom: 25px; font-size: 1.1rem;\">\n                    \"Coragem para arriscar. Determinação para crescer. Conectar para transformar. Cuidar para sustentabilizar.\"\n                </div>\n\n                <div class=\"essencia-grid\">\n                    <div class=\"essencia-card\">\n                        <div class=\"essencia-icon\"><i class=\"fa-solid fa-bullseye\"></i></div>\n                        <h3>Missão</h3>\n                        <p style=\"font-size: 0.85rem; margin-top: 10px; color: var(--text-dark); text-align: justify;\">\n                            Conectar as pessoas aos ideais de beleza através do cuidar-se, proporcionando autoestima e bem-estar, sendo a marca preferida com rentabilidade acima do mercado.\n                        </p>\n                    </div>\n\n                    <div class=\"essencia-card\">\n                        <div class=\"essencia-icon\"><i class=\"fa-solid fa-eye\"></i></div>\n                        <h3>Visão</h3>\n                        <p style=\"font-size: 0.85rem; margin-top: 10px; color: var(--text-dark); text-align: justify;\">\n                            Chegar em 2030 com uma governança corporativa sustentável, uma sucessão estruturada e uma estrutura organizacional eficiente e eficaz.\n                        </p>\n                    </div>\n\n                    <div class=\"essencia-card\">\n                        <div class=\"essencia-icon\"><i class=\"fa-solid fa-heart\"></i></div>\n                        <h3>Valores Oficiais</h3>\n                        <div class=\"valores-list\">\n                            <div class=\"valor-item\">Diversidade</div>\n                            <div class=\"valor-item\">Imparcialidade</div>\n                            <div class=\"valor-item\">Engajamento</div>\n                            <div class=\"valor-item\">Ética</div>\n                            <div class=\"valor-item\">Lealdade</div>\n                            <div class=\"valor-item\">Respeito</div>\n                            <div class=\"valor-item\">Honestidade</div>\n                            <div class=\"valor-item\">Responsabilidade</div>\n                            <div class=\"valor-item\">Sustentabilidade</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"regulamento\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Diretrizes Práticas</p>\n                <h2>Regulamento Interno 2026</h2>\n                <p>Documento oficial que retrata o procedimento correto de cada função, regras de qualidade e técnicas de venda para garantir a total satisfação do cliente.</p>\n\n                <div class=\"rules-grid\">\n                    <div class=\"rules-card\">\n                        <div>\n                            <h3 style=\"font-size: 1.3rem; margin-bottom: 12px; color: var(--primary-green);\">\n                                <i class=\"fa-solid fa-clipboard-user\" style=\"color: var(--accent-gold); margin-right: 10px;\"></i> Deveres Oficiais (Parte 1)\n                            </h3>\n                            <p style=\"font-size: 0.88rem; color: var(--text-muted); text-align: justify; margin-bottom: 15px;\">\n                                Inclui exigências fundamentais como assiduidade, pontualidade no cumprimento de horários, sigilo total profissional e obediência ágil aos superiores da empresa.\n                            </p>\n                        </div>\n                        <button class=\"btn-gold-outline\" onclick=\"window.openRegulamentoDetail('deveres1')\">VER DEVERES PARTE 1</button>\n                    </div>\n\n                    <div class=\"rules-card\">\n                        <div>\n                            <h3 style=\"font-size: 1.3rem; margin-bottom: 12px; color: var(--primary-green);\">\n                                <i class=\"fa-solid fa-shirt\" style=\"color: var(--accent-gold); margin-right: 10px;\"></i> Deveres Oficiais (Parte 2)\n                            </h3>\n                            <p style=\"font-size: 0.88rem; color: var(--text-muted); text-align: justify; margin-bottom: 15px;\">\n                                Contempla os parâmetros estritos de fardamento, maquiagem obrigatória, restrição a adereços visíveis e a regulamentação sobre Equipamentos de Proteção Individual (EPI).\n                            </p>\n                        </div>\n                        <button class=\"btn-action\" onclick=\"window.openRegulamentoDetail('deveres2')\">VER DEVERES PARTE 2</button>\n                    </div>\n                </div>\n\n                <!-- Botões para leitura na íntegra no Google Drive e leitor integrado -->\n                <div style=\"text-align: center; margin-top: 25px; display: flex; flex-direction: column; gap: 12px; align-items: center;\">\n                    <a href=\"https://docs.google.com/document/d/1QDnx47O0WPl6mugH0_XjFVVHjxMqu8Jx/edit?usp=sharing\" target=\"_blank\" class=\"btn-action\" style=\"width: 100%; max-width: 650px; justify-content: center; font-size: 0.95rem; text-decoration: none; padding: 18px 24px; background: linear-gradient(135deg, #0F3D2E 0%, #155541 100%); border: 2px solid var(--accent-gold); box-shadow: 0 10px 20px -5px rgba(212, 175, 55, 0.4);\">\n                        <i class=\"fa-solid fa-arrow-up-right-from-square\"></i> ABRIR REGULAMENTO INTERNO NA ÍNTEGRA (NO GOOGLE DRIVE)\n                    </a>\n                    <button class=\"btn-gold-outline\" onclick=\"window.openRegulamentoIntegra()\" style=\"width: 100%; max-width: 650px; justify-content: center; font-size: 0.85rem;\">\n                        <i class=\"fa-solid fa-file-pdf\"></i> VISUALIZAR REGULAMENTO INTERNO NA ÍNTEGRA (NO PORTAL)\n                    </button>\n                </div>\n            </div>\n        </section>\n\n        <section id=\"organograma\">\n            <div class=\"glass-card\" style=\"text-align: center;\">\n                <p class=\"title-pre\">Quadro de Governança</p>\n                <h2>Organograma do Grupo</h2>\n                <p style=\"margin-bottom: 25px;\">Estrutura oficial de governança e hierarquia organizacional do Grupo C. Diniz:</p>\n\n                <div style=\"width: 100%; display: flex; justify-content: center; align-items: center; padding: 10px 0;\">\n                    <img src=\"https://lh3.googleusercontent.com/d/1v-Xi-_ycEWq_jBIoUd79GYFCxfHlfeZa\" alt=\"Estrutura de Governança - Grupo C. Diniz\" style=\"width: 100%; max-width: 1000px; height: auto; border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.08); border: 1px solid rgba(212, 175, 55, 0.25); transition: var(--transition-smooth);\" onerror=\"this.onerror=null; this.src='https://drive.google.com/uc?export=view&id=1v-Xi-_ycEWq_jBIoUd79GYFCxfHlfeZa';\">\n                </div>\n            </div>\n        </section>\n\n        <section id=\"politicas\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Parâmetros Normativos</p>\n                <h2>Políticas Organizacionais (22)</h2>\n                <p>As 22 diretrizes de compliance unificadas para regulamentar nossas operações e assegurar a transparência:</p>\n\n                <!-- Botão de acesso à pasta principal de políticas no Drive -->\n                <div style=\"display: flex; gap: 15px; flex-wrap: wrap; margin-bottom: 25px;\">\n                    <a href=\"https://drive.google.com/drive/folders/1I2ehKSjWY8MnTOgs9ryjuminh5U0R1GY?usp=sharing\" target=\"_blank\" class=\"btn-action\" style=\"text-decoration: none;\">\n                        <i class=\"fa-solid fa-folder-open\"></i> ABRIR PASTA DE POLÍTICAS NO GOOGLE DRIVE\n                    </a>\n                </div>\n\n                <div class=\"policies-controls\">\n                    <input type=\"text\" class=\"policy-search\" id=\"policySearchInput\" placeholder=\"Buscar política por palavra-chave...\" oninput=\"window.filterPolicies()\">\n                    <button class=\"policy-filter-btn active\" id=\"filter-all\" onclick=\"window.setPolicyFilter('todas')\">Todas</button>\n                    <button class=\"policy-filter-btn\" id=\"filter-adm\" onclick=\"window.setPolicyFilter('adm')\">Gestão & Governança</button>\n                    <button class=\"policy-filter-btn\" id=\"filter-rh\" onclick=\"window.setPolicyFilter('rh')\">Recursos Humanos (Gente)</button>\n                </div>\n\n                <div class=\"policy-list-container\" id=\"policyListContainer\">\n                    <!-- Gerado dinamicamente via JS -->\n                </div>\n            </div>\n        </section>\n\n        <section id=\"beneficios\">\n            <div class=\"glass-card\">\n                <p class=\"title-pre\">Nossas Vantagens</p>\n                <h2>Portfólio de Benefícios Oficiais</h2>\n                <p>Relação oficial de vantagens do Grupo C. Diniz voltadas à capacitação, saúde, bem-estar e incentivo ao desempenho:</p>\n\n                <div class=\"benefits-grid\">\n                    <div class=\"benefit-card\">\n                        <h3><i class=\"fa-solid fa-graduation-cap\"></i> Educação / Alimentação</h3>\n                        <ul>\n                            <li>Auxílio educação e cursos (empresa 50%)</li>\n                            <li>Treinamentos internos constantes</li>\n                            <li>Parceria Unopar (Desconto de 20%)</li>\n                            <li>Parceria Escola Integra (Desconto de 10%)</li>\n                            <li>VA R$ 350,00</li>\n                        </ul>\n                    </div>\n\n                    <div class=\"benefit-card\">\n                        <h3><i class=\"fa-solid fa-heart-pulse\"></i> Saúde / Bem-Estar</h3>\n                        <ul>\n                            <li>Plano odontológico (Unimed 80 benefícios)</li>\n                            <li>Coparticipação - Hospital São Gabriel</li>\n                            <li>Telemedicina - (Conexa Saúde)</li>\n                            <li>Telepsicologia - (Conexa Saúde)</li>\n                            <li>Nutricionista - (Conexa Saúde)</li>\n                            <li>Parcerias com academia + Wellhub</li>\n                            <li>Descontos em farmácia e laboratório - (Cartão Caju + Unimed)</li>\n                        </ul>\n                    </div>\n\n                    <div class=\"benefit-card\">\n                        <h3><i class=\"fa-solid fa-fire\"></i> Motivação & Incentivos</h3>\n                        <ul>\n                            <li>Prêmio por tempo de trabalho</li>\n                            <li>Premiação Trimestral IAF / Anual IAF</li>\n                            <li>Premiação mensal AF</li>\n                            <li>Premiação Melhores do Ano</li>\n                            <li>Especial Hits (Loja + VD)</li>\n                            <li>Brinde por Elogio de Cliente</li>\n                            <li>Desconto em produtos O Boticário</li>\n                        </ul>\n                    </div>\n                </div>\n\n                <div class=\"closing-quote-card\">\n                    <p class=\"closing-text\">\n                        \"Desejo uma leitura reflexiva, pois há dois momentos importantes do aprendizado: o primeiro quando absorvemos a informação, mas o segundo e mais importante quando essas informações saem, de nós, através dos nossos atos.\"\n                    </p>\n                    <p class=\"closing-author\">\n                        Carmen Neves Diniz <span style=\"font-weight: 300; text-transform: none; letter-spacing: 0;\">— Presidente e Fundadora</span>\n                    </p>\n                </div>\n\n                <div style=\"text-align: center; margin-top: 30px;\">\n                    <button class=\"btn-action\" onclick=\"window.openEthicsModal()\">\n                        CÓDIGO DE ÉTICA E CONDUTA NA ÍNTEGRA <i class=\"fa-solid fa-scale-balanced\"></i>\n                    </button>\n                </div>\n            </div>\n        </section>\n\n    </main>\n\n    <div class=\"modal-overlay\" id=\"portalModal\">\n        <div class=\"modal-content\">\n            <div class=\"modal-header\">\n                <button class=\"modal-close\" onclick=\"window.closePortalModal()\">&times;</button>\n                <h3 id=\"modalTitle\">Título do Modal</h3>\n                <p id=\"modalSubtitle\" style=\"color: rgba(255,255,255,0.85); font-size: 0.8rem; margin-bottom: 0;\">Subtítulo</p>\n            </div>\n            <div class=\"modal-body\" id=\"modalBody\">\n                <!-- Conteúdo dinâmico -->\n            </div>\n        </div>\n    </div>\n\n    <script>\n        const POLICIES_DATA = [\n            { \n                id: 1, \n                title: \"Política de Prevenção e Combate ao Assédio Moral e Sexual\", \n                category: \"rh\", \n                icon: \"fa-shield-heart\", \n                docUrl: \"https://docs.google.com/document/d/1oiLvcJO4T_5pxSGZfECppI-uVxLHMsjj/edit?usp=sharing\",\n                objective: \"Estabelecer um ambiente de trabalho seguro, respeitoso e inclusivo, livre de qualquer forma de assédio moral ou sexual, em alinhamento com a essência, missão, visão e valores do Grupo C. Diniz.\",\n                fullText: \"\"\n            },\n            { \n                id: 2, \n                title: \"Política de Banco de Horas\", \n                category: \"rh\", \n                icon: \"fa-clock\", \n                docUrl: \"https://docs.google.com/document/d/14h1oN4o5vwP0ndGsQ6gD0MVbg6g8dqY3/edit?usp=sharing\",\n                objective: \"Implementar uma política de Banco de Horas que promova flexibilidade e justiça no uso de horas extras, alinhada à missão do Grupo C. Diniz de conectar e cuidar das pessoas.\",\n                fullText: \"\"\n            },\n            { \n                id: 3, \n                title: \"Política de Benefícios\", \n                category: \"rh\", \n                icon: \"fa-gift\", \n                docUrl: \"https://docs.google.com/document/d/1c1fet5wmNGShingaXECmtU997qokMzsX/edit?usp=sharing\",\n                objective: \"Estabelecer uma política de benefícios que vá além do padrão de mercado, alinhada com a missão, visão e valores do Grupo C. Diniz.\",\n                fullText: \"\"\n            },\n            { \n                id: 4, \n                title: \"Política de Cargos e Salários\", \n                category: \"rh\", \n                icon: \"fa-stairs\", \n                docUrl: \"https://docs.google.com/document/d/1Mul5ds251n64IjKzB4FHtooAf-g2ULzp/edit?usp=sharing\",\n                objective: \"Estabelecer uma estrutura salarial justa, competitiva e sustentável, que valorize as competências e contribuições dos colaboradores.\",\n                fullText: \"\"\n            },\n            { \n                id: 5, \n                title: \"Política de Compliance Trabalhista\", \n                category: \"adm\", \n                icon: \"fa-gavel\", \n                docUrl: \"https://docs.google.com/document/d/1JD_iOoppfy3p2HaPbCzgOb4NRgCmCtaT/edit?usp=sharing\",\n                objective: \"Garantir o cumprimento integral das leis trabalhistas e das normas regulamentadoras, promovendo um ambiente justo, seguro e ético.\",\n                fullText: \"\"\n            },\n            { \n                id: 6, \n                title: \"Política de Comunicação Interna\", \n                category: \"adm\", \n                icon: \"fa-comments\", \n                docUrl: \"https://docs.google.com/document/d/1YeqbNIv59pXTPAIsFuSeQ0eGhCIzAKkK/edit?usp=sharing\",\n                objective: \"Criar uma rede de comunicação transparente, acessível e eficaz, que fortaleça a integração entre os colaboradores.\",\n                fullText: \"\"\n            },\n            { \n                id: 7, \n                title: \"Política de Contratação de Funcionários\", \n                category: \"rh\", \n                icon: \"fa-user-plus\", \n                docUrl: \"https://docs.google.com/document/d/1bFnk3rvPiIm_dSVBzz5leuSJMpOmC7Zo/edit?usp=sharing\",\n                objective: \"Atrair e selecionar talentos alinhados com a essência e cultura do Grupo C. Diniz.\",\n                fullText: \"\"\n            },\n            { \n                id: 8, \n                title: \"Política de Desempenho e Feedback\", \n                category: \"rh\", \n                icon: \"fa-chart-line\", \n                docUrl: \"https://docs.google.com/document/d/1oPrhydxZ1bV1WJNFz1BgxqJv1rphNAiV/edit?usp=sharing\",\n                objective: \"Promover um ambiente de constante desenvolvimento e aprimoramento através da cultura de feedback contínuo.\",\n                fullText: \"\"\n            },\n            { \n                id: 9, \n                title: \"Política de Desenvolvimento de Pessoas\", \n                category: \"rh\", \n                icon: \"fa-graduation-cap\", \n                docUrl: \"https://docs.google.com/document/d/1IvU2amZb8pM3yBsq_ejaoEyBbhSAJo3t/edit?usp=sharing\",\n                objective: \"Promover o crescimento contínuo dos colaboradores, alavancando competências e potencial individual.\",\n                fullText: \"\"\n            },\n            { \n                id: 10, \n                title: \"Política de Gestão de Conflitos e Mediação\", \n                category: \"adm\", \n                icon: \"fa-handshake-angle\", \n                docUrl: \"https://docs.google.com/document/d/1NkxQHe-KlEY9lXrf5AFeZbR6S_vqjPKJ/edit?usp=sharing\",\n                objective: \"Facilitar a resolução pacífica e imparcial de divergências com diálogo aberto e respeito.\",\n                fullText: \"\"\n            },\n            { \n                id: 11, \n                title: \"Política de Gestão de Desligamento\", \n                category: \"rh\", \n                icon: \"fa-user-minus\", \n                docUrl: \"https://docs.google.com/document/d/193PG5lac-YJphKyFO-wBPKoVeYFmBkJ6/edit?usp=sharing\",\n                objective: \"Garantir um processo de desligamento humanizado, empático e respeitoso.\",\n                fullText: \"\"\n            },\n            { \n                id: 12, \n                title: \"Política de Home Office e Trabalho Híbrido\", \n                category: \"adm\", \n                icon: \"fa-laptop-house\", \n                docUrl: \"https://drive.google.com/file/d/1lldTHL327zTLISoGUaPHyx5NYhADL4pt/view?usp=drivesdk\",\n                objective: \"Regulamentar o trabalho flexível mantendo eficiência, segurança e equilíbrio.\",\n                fullText: \"\"\n            },\n            { \n                id: 13, \n                title: \"Política de Integridade e Ética\", \n                category: \"adm\", \n                icon: \"fa-scale-balanced\", \n                docUrl: \"https://docs.google.com/document/d/1c71BE5e47i8xbhmelFjfOpnHWaUQGZ-i/edit?usp=sharing\",\n                objective: \"Promover cultura de integridade, honestidade e combate a conflitos de interesse.\",\n                fullText: \"\"\n            },\n            { \n                id: 14, \n                title: \"Política de Pontualidade e Faltas\", \n                category: \"rh\", \n                icon: \"fa-user-clock\", \n                docUrl: \"https://docs.google.com/document/d/1ehIQIyRFe9wBnl9nP6mAZ2wr6GHVYQSk/edit?usp=sharing\",\n                objective: \"Estabelecer diretrizes para cumprimento de jornada e gestão de ausências.\",\n                fullText: \"\"\n            },\n            { \n                id: 15, \n                title: \"Política de Promoção\", \n                category: \"rh\", \n                icon: \"fa-circle-arrow-up\", \n                docUrl: \"https://docs.google.com/document/d/19nfva3Lhx8MuWImIytsv8-g3PrwSexcj/edit?usp=sharing\",\n                objective: \"Regulamentar a progressão de carreira com base na meritocracia e competências.\",\n                fullText: \"\"\n            },\n            { \n                id: 16, \n                title: \"Política de Reconhecimento\", \n                category: \"rh\", \n                icon: \"fa-award\", \n                docUrl: \"https://docs.google.com/document/d/1q5mLesBYFk0hySzfx8ISV_bUdOvHDn_5/edit?usp=sharing\",\n                objective: \"Fomentar a valorização e celebração de resultados e atitudes exemplares.\",\n                fullText: \"\"\n            },\n            { \n                id: 17, \n                title: \"Política de Recrutamento e Seleção\", \n                category: \"rh\", \n                icon: \"fa-users-viewfinder\", \n                docUrl: \"https://docs.google.com/document/d/1I7CwSjU-F00iX0U25qF-0_lYv8OlBGjd/edit?usp=sharing\",\n                objective: \"Assegurar seleção justa, inclusiva e alinhada à essência do Grupo.\",\n                fullText: \"\"\n            },\n            { \n                id: 18, \n                title: \"Política de Retenção de Talentos\", \n                category: \"rh\", \n                icon: \"fa-heart\", \n                docUrl: \"https://docs.google.com/document/d/1B3cIet_pLzLAF6BQMcJwebUVMSRV4Y-e/edit?usp=sharing\",\n                objective: \"Iniciativas para fortalecimento de vínculo e permanência de talentos.\",\n                fullText: \"\"\n            },\n            { \n                id: 19, \n                title: \"Política de Saúde e Segurança no Trabalho\", \n                category: \"adm\", \n                icon: \"fa-helmet-safety\", \n                docUrl: \"https://docs.google.com/document/d/1Bv3t60TQC38_GqkWg4Qv24qe9glE1Xoi/edit?usp=sharing\",\n                objective: \"Garantir ambiente seguro e prevenção de acidentes e doenças ocupacionais.\",\n                fullText: \"\"\n            },\n            { \n                id: 20, \n                title: \"Política de Viagens e Reembolso de Despesas\", \n                category: \"adm\", \n                icon: \"fa-receipt\", \n                docUrl: \"https://docs.google.com/document/d/19qJ2B5QR6MbzOUvvzdwFTbegwxVYIlkG/edit?usp=sharing\",\n                objective: \"Orientar procedimentos e prestação de contas de deslocamentos corporativos.\",\n                fullText: \"\"\n            },\n            { \n                id: 21, \n                title: \"Política de Diversidade, Equidade e Inclusão (DEI)\", \n                category: \"rh\", \n                icon: \"fa-people-group\", \n                docUrl: \"https://docs.google.com/document/d/1_9UaCAbbKCD9x_Q_PAsqIDL0_brz1IGC/edit?usp=sharing\",\n                objective: \"Valorizar diferenças e garantir igualdade de oportunidades a todos os colaboradores.\",\n                fullText: \"\"\n            },\n            { \n                id: 22, \n                title: \"Política de Uso de Equipamentos, Veículos e Tecnologia\", \n                category: \"adm\", \n                icon: \"fa-key\", \n                docUrl: \"https://drive.google.com/file/d/1CJ-mybLotfuwWwLVn6Xjw3sJYODLcup3/view?usp=sharing\",\n                objective: \"Uso seguro, ético e conservativo do patrimônio tecnológico e operacional da empresa.\",\n                fullText: \"\"\n            }\n        ];\n\n        const REG_TEXTS = {\n            deveres1: {\n                title: \"Deveres dos Funcionários (Parte 1)\",\n                subtitle: \"REGRAS COMPORTAMENTAIS GERAIS\",\n                content: \"<div class=\\\"document-full-text\\\"><h4>Deveres dos Funcionários</h4><p>São deveres dos funcionários, além dos interesses aos cargos que ocupa na empresa:</p><ul><li><strong>Assiduidade:</strong> Frequência e presença regular diária ao trabalho.</li><li><strong>Pontualidade:</strong> Cumprir rigorosamente os horários pré-estabelecidos.</li><li><strong>Lealdade:</strong> Demonstrar confiança em todas as suas ações, mantendo sigilo corporativo.</li><li><strong>Respeito à Hierarquia:</strong> Cumprir prontamente as solicitações dos superiores.</li><li><strong>Prevenção de Irregularidades:</strong> Levar ao conhecimento da diretoria qualquer irregularidade.</li><li><strong>Foco Operacional:</strong> Evitar dispersões e desperdício de tempo durante o expediente.</li></ul></div>\"\n            },\n            deveres2: {\n                title: \"Deveres dos Funcionários (Parte 2)\",\n                subtitle: \"ZELO, IMAGEM E SEGURANÇA\",\n                content: \"<div class=\\\"document-full-text\\\"><h4>Aparência, Fardamento e Segurança</h4><ul><li><strong>Economia e Conservação:</strong> Zelar pela conservação de todo material confiado.</li><li><strong>Qualidade de Atendimento:</strong> Manter-se sempre cortês e sorridente ao tratar clientes.</li><li><strong>Uniformização Perfeita:</strong> Trabalhar fardado, alinhado e maquiada conforme padrão.</li><li><strong>Regras de Cabelo e Adereços:</strong> Brincos discretos e cabelos devidamente alinhados.</li><li><strong>Uso de EPI de Estoque:</strong> Utilização obrigatória de botas, luvas e cinta de proteção.</li></ul></div>\"\n            }\n        };\n\n        let activeFilter = \"todas\";\n\n        window.scrollToSlide = function(id) {\n            const scrollContainer = document.getElementById('main-scroll');\n            const targetSection = document.getElementById(id);\n            if (scrollContainer && targetSection) {\n                scrollContainer.scrollTo({\n                    top: targetSection.offsetTop,\n                    behavior: 'smooth'\n                });\n            }\n        };\n\n        window.openNavMenu = function() {\n            const sections = document.querySelectorAll('section');\n            let menuHtml = \"<div style=\\\"display:flex; flex-direction:column; gap:10px;\\\">\";\n            sections.forEach(s => {\n                const title = document.querySelector(`.nav-dot[data-target=\"${s.id}\"]`)?.getAttribute('title') || s.id.toUpperCase();\n                menuHtml += `<button class=\"btn-gold-outline\" style=\"width:100%; justify-content:center;\" onclick=\"window.scrollToSlide('${s.id}'); window.closePortalModal();\">${title}</button>`;\n            });\n            menuHtml += \"</div>\";\n            window.openPortalModal(\"Navegação do Onboarding\", \"IR PARA UM CONTEÚDO\", menuHtml);\n        };\n\n        window.openPortalModal = function(title, subtitle, contentHtml) {\n            const portalModal = document.getElementById('portalModal');\n            const modalTitle = document.getElementById('modalTitle');\n            const modalSubtitle = document.getElementById('modalSubtitle');\n            const modalBody = document.getElementById('modalBody');\n\n            if (modalTitle) modalTitle.innerText = title;\n            if (modalSubtitle) modalSubtitle.innerText = subtitle;\n            if (modalBody) modalBody.innerHTML = contentHtml;\n            if (portalModal) portalModal.classList.add('active');\n        };\n\n        window.closePortalModal = function() {\n            const portalModal = document.getElementById('portalModal');\n            if (portalModal) portalModal.classList.remove('active');\n        };\n\n        window.renderPolicies = function() {\n            const container = document.getElementById('policyListContainer');\n            if (!container) return;\n            container.innerHTML = \"\";\n            const searchInput = document.getElementById('policySearchInput');\n            const searchVal = (searchInput ? searchInput.value : \"\").toLowerCase();\n\n            const filtered = POLICIES_DATA.filter(policy => {\n                if (activeFilter !== \"todas\" && policy.category !== activeFilter) return false;\n                if (searchVal && !policy.title.toLowerCase().includes(searchVal) && !policy.objective.toLowerCase().includes(searchVal)) return false;\n                return true;\n            });\n\n            if (filtered.length === 0) {\n                container.innerHTML = \"<p style=\\\"grid-column:1/-1; text-align:center; padding: 20px; color: var(--text-muted); font-weight: 500;\\\">Nenhuma diretriz encontrada.</p>\";\n                return;\n            }\n\n            filtered.forEach(policy => {\n                const pill = document.createElement('div');\n                pill.className = \"policy-item-pill\";\n                pill.style.justifyContent = \"space-between\";\n                pill.onclick = () => window.openPolicyDetail(policy.id);\n                const documentAction = policy.docUrl ? `\n                    <a href=\"${policy.docUrl}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-gold-outline\" style=\"padding: 6px 12px; font-size: 0.7rem; white-space: nowrap; text-decoration: none;\" onclick=\"event.stopPropagation();\" title=\"Abrir arquivo oficial no Google Drive\">\n                        <i class=\"fa-solid fa-arrow-up-right-from-square\"></i> Abrir Doc\n                    </a>\n                ` : `\n                    <span class=\"btn-gold-outline\" style=\"padding: 6px 12px; font-size: 0.7rem; white-space: nowrap; opacity: 0.65; cursor: default;\" title=\"Documento ainda não disponível\">\n                        <i class=\"fa-solid fa-clock\"></i> Em atualização\n                    </span>\n                `;\n                pill.innerHTML = `\n                    <div style=\"display: flex; align-items: center; gap: 12px; flex: 1;\">\n                        <i class=\"fa-solid ${policy.icon}\"></i>\n                        <span>${policy.title}</span>\n                    </div>\n                    ${documentAction}\n                `;\n                container.appendChild(pill);\n            });\n        };\n\n        window.setPolicyFilter = function(cat) {\n            activeFilter = cat;\n            document.querySelectorAll('.policy-filter-btn').forEach(btn => btn.classList.remove('active'));\n            if (cat === \"todas\") document.getElementById('filter-all')?.classList.add('active');\n            if (cat === \"adm\") document.getElementById('filter-adm')?.classList.add('active');\n            if (cat === \"rh\") document.getElementById('filter-rh')?.classList.add('active');\n            window.renderPolicies();\n        };\n\n        window.filterPolicies = function() {\n            window.renderPolicies();\n        };\n\n        window.openPolicyDetail = function(id) {\n            const policy = POLICIES_DATA.find(p => p.id === id);\n            if (!policy) return;\n\n            const docUrl = policy.docUrl || \"\";\n            const objectiveText = policy.objective || \"Objetivo não cadastrado.\";\n            const fileIdMatch = docUrl.match(/\\/d\\/([a-zA-Z0-9_-]+)/);\n            const embedUrl = fileIdMatch\n                ? `https://drive.google.com/file/d/${fileIdMatch[1]}/preview`\n                : \"\";\n            const documentActions = docUrl ? `\n                <div style=\"display: flex; gap: 12px; margin-bottom: 20px; flex-wrap: wrap;\">\n                    <a href=\"${docUrl}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-action\" style=\"text-decoration: none; font-size: 0.85rem; padding: 12px 20px;\">\n                        <i class=\"fa-solid fa-arrow-up-right-from-square\"></i> ABRIR DOCUMENTO NA ÍNTEGRA NO GOOGLE DRIVE\n                    </a>\n                </div>\n            ` : `\n                <div style=\"padding: 16px 18px; margin-bottom: 20px; border-radius: 12px; background: rgba(212, 175, 55, 0.12); border: 1px solid rgba(212, 175, 55, 0.35); color: var(--primary-green);\">\n                    <i class=\"fa-solid fa-circle-info\" style=\"color: var(--accent-gold); margin-right: 8px;\"></i>\n                    ${policy.availabilityMessage || 'O documento oficial desta política ainda não está disponível.'}\n                </div>\n            `;\n\n            const fullTextContent = `\n                <div class=\"document-full-text\">\n                    ${documentActions}\n\n                    <h4>1. OBJETIVO DA DIRETRIZ OFICIAL</h4>\n                    <p style=\"text-align: justify; line-height: 1.7; font-weight: 500;\">${objectiveText}</p>\n                    <hr style=\"border:1px solid var(--accent-gold); margin: 15px 0;\">\n                    \n                    <h4>2. CONTEÚDO E DIRETRIZES DA POLÍTICA</h4>\n                    ${policy.fullText ? policy.fullText : '<p>Acesse o documento oficial no Google Docs para a leitura completa.</p>'}\n\n                    ${embedUrl ? `\n                        <hr style=\"border:1px solid var(--accent-gold); margin: 20px 0;\">\n                        <h4>3. VISUALIZAÇÃO INTEGRADA DO DOCUMENTO</h4>\n                        <div style=\"width: 100%; height: 500px; border-radius: 12px; overflow: hidden; border: 2px solid var(--accent-gold); margin-top: 10px;\">\n                            <iframe src=\"${embedUrl}\" title=\"${policy.title}\" width=\"100%\" height=\"100%\" style=\"border:none;\" loading=\"lazy\" allow=\"autoplay\"></iframe>\n                        </div>\n                    ` : ''}\n                </div>\n            `;\n            \n            window.openPortalModal(policy.title, \"DIRETRIZ DA POLÍTICA OFICIAL (GRUPO C. DINIZ)\", fullTextContent);\n        };\n\n        window.openRegulamentoDetail = function(key) {\n            const r = REG_TEXTS[key];\n            if (r) {\n                window.openPortalModal(r.title, r.subtitle, r.content);\n            }\n        };\n\n        window.openRegulamentoIntegra = function() {\n            const drivePdfUrl = \"https://docs.google.com/document/d/1QDnx47O0WPl6mugH0_XjFVVHjxMqu8Jx/edit?usp=sharing\";\n            const driveEmbedUrl = \"https://docs.google.com/document/d/1QDnx47O0WPl6mugH0_XjFVVHjxMqu8Jx/preview\";\n            const fullHtml = `\n                <div class=\"document-full-text\">\n                    <div style=\"display: flex; gap: 12px; margin-bottom: 15px; flex-wrap: wrap; justify-content: space-between; align-items: center;\">\n                        <span style=\"font-weight: 600; color: var(--primary-green); font-size: 0.95rem;\"><i class=\"fa-solid fa-file-lines\"></i> Regulamento Interno 2026 Oficial</span>\n                        <a href=\"${drivePdfUrl}\" target=\"_blank\" class=\"btn-action\" style=\"text-decoration: none; font-size: 0.85rem; padding: 10px 20px;\">\n                            <i class=\"fa-solid fa-arrow-up-right-from-square\"></i> ABRIR NO GOOGLE DRIVE\n                        </a>\n                    </div>\n                    <div style=\"width: 100%; height: 72vh; min-height: 520px; border-radius: 12px; overflow: hidden; border: 2px solid var(--accent-gold); box-shadow: 0 10px 25px rgba(0,0,0,0.15);\">\n                        <iframe src=\"${driveEmbedUrl}\" width=\"100%\" height=\"100%\" style=\"border:none;\" allow=\"autoplay\"></iframe>\n                    </div>\n                </div>\n            `;\n            window.openPortalModal(\"Regulamento Interno 2026 na Íntegra\", \"DOCUMENTO OFICIAL COMPLETO (GRUPO C. DINIZ)\", fullHtml);\n        };\n\n        window.openEthicsModal = function() {\n            const docUrl = \"https://drive.google.com/file/d/1bTZY8zpkkBfH_jU-Yrka3Hf8FIV8vqAH/view?usp=sharing\";\n            const embedUrl = \"https://drive.google.com/file/d/1bTZY8zpkkBfH_jU-Yrka3Hf8FIV8vqAH/preview\";\n            \n            const fullEthicsHtml = `\n                <div class=\"document-full-text\">\n                    <div style=\"display: flex; gap: 12px; margin-bottom: 20px; flex-wrap: wrap;\">\n                        <a href=\"${docUrl}\" target=\"_blank\" class=\"btn-action\" style=\"text-decoration: none; font-size: 0.85rem; padding: 12px 20px;\">\n                            <i class=\"fa-solid fa-arrow-up-right-from-square\"></i> ABRIR CÓDIGO DE ÉTICA NA ÍNTEGRA NO GOOGLE DOCS\n                        </a>\n                    </div>\n\n                    <h3>CÓDIGO DE ÉTICA E CONDUTA - GRUPO C. DINIZ</h3>\n                    \n                    <h4>MENSAGEM DA PRESIDÊNCIA</h4>\n                    <p>\"O Código de conduta é nossa diretriz por um caminho ético, que nos orienta como agir com todos aqueles que de certa forma fazem parte ou se relacionam com o Grupo.\"</p>\n                    <p><strong>Carmen Neves Diniz</strong> — <em>Presidente e Fundadora</em></p>\n\n                    <h4>CULTURA, VALORES & CANAL DE OUVIDORIA</h4>\n                    <p>Inadmissibilidade de discriminações ou assédios. Comprometimento irrestrito com integridade, sigilo e transparência em todas as operações.</p>\n                    <p>Canal Oficial de Ética e Ouvidoria: <strong>ouvidoria@grupocdiniz.com.br</strong></p>\n\n                    <hr style=\"border:1px solid var(--accent-gold); margin: 20px 0;\">\n                    <h4>VISUALIZAÇÃO INTEGRADA DO DOCUMENTO</h4>\n                    <div style=\"width: 100%; height: 500px; border-radius: 12px; overflow: hidden; border: 2px solid var(--accent-gold); margin-top: 10px;\">\n                        <iframe src=\"${embedUrl}\" width=\"100%\" height=\"100%\" style=\"border:none;\"></iframe>\n                    </div>\n                </div>\n            `;\n            window.openPortalModal(\"Código de Ética e Conduta\", \"DOCUMENTO OFICIAL (GRUPO C. DINIZ)\", fullEthicsHtml);\n        };\n\n        document.addEventListener('DOMContentLoaded', () => {\n            window.renderPolicies();\n\n            const scrollContainer = document.getElementById('main-scroll');\n            const dots = document.querySelectorAll('.nav-dot');\n            const sections = document.querySelectorAll('section');\n\n            dots.forEach(dot => {\n                dot.addEventListener('click', () => {\n                    const targetId = dot.getAttribute('data-target');\n                    window.scrollToSlide(targetId);\n                });\n            });\n\n            if (scrollContainer) {\n                scrollContainer.addEventListener('scroll', () => {\n                    let current = '';\n                    const scrollPos = scrollContainer.scrollTop + (window.innerHeight / 3);\n\n                    sections.forEach(section => {\n                        if (scrollPos >= section.offsetTop) {\n                            current = section.getAttribute('id');\n                        }\n                    });\n\n                    dots.forEach(dot => {\n                        dot.classList.remove('active');\n                        if (dot.getAttribute('data-target') === current) {\n                            dot.classList.add('active');\n                        }\n                    });\n                });\n            }\n\n            window.onclick = function(event) {\n                const portalModal = document.getElementById('portalModal');\n                if (event.target === portalModal) {\n                    window.closePortalModal();\n                }\n            };\n        });\n    </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/favicon.ico') return new Response(null, { status: 204 });
    return new Response(HTML, {
      headers: {
        'content-type': 'text/html; charset=UTF-8',
        'cache-control': 'public, max-age=300',
        'x-content-type-options': 'nosniff',
        'referrer-policy': 'strict-origin-when-cross-origin',
        'permissions-policy': 'camera=(), microphone=(), geolocation=()'
      }
    });
  }
};
